type Entry = { id: string; lastAccess: number; size: number };

interface IPolicy {
  onAccess(entry: Entry): void;
  onEvict(entries: Entry[]): boolean;
}

class LRUPolicy implements IPolicy {
  onAccess(_e: Entry) { /* update recency */ }
  onEvict(_entries: Entry[]): boolean { /* evict oldest */ return true; }
}

class TTLPolicy implements IPolicy {
  constructor(private ttl: number) {}
  onAccess(_e: Entry) { /* refresh */ }
  onEvict(_entries: Entry[]): boolean { /* compare now - lastAccess > ttl */ return true; }
